try (var scope = new StructuredTaskScope.ShutdownOnFailure()) {
    var user  = scope.fork(() -> findUser());     // runs in its own thread
    var order = scope.fork(() -> fetchOrder());
    scope.joinUntil(deadline).throwIfFailed();    // deadline + first failure cancels
    return new Response(user.get(), order.get());  // both subtasks finished
}

